/* ===================================================
   高機能アナログ時計 Webアプリケーション スタイル定義
   =================================================== */

:root {
  --font-main: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --font-mono: 'SF Mono', Monaco, Inconsolata, 'Fira Mono', 'Droid Sans Mono', monospace;
  --bg-app-default: #0f172a;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --panel-bg: rgba(30, 41, 59, 0.7);
  --panel-border: rgba(255, 255, 255, 0.1);
  --panel-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.5);
  --accent-color: #38bdf8;
  --transition-speed: 0.3s;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font-main);
  background-color: var(--bg-app-default);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
}

/* アプリケーション全体コンテナ */
.clock-app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 24px 16px;
  background: radial-gradient(circle at 50% 30%, #1e293b 0%, #0f172a 100%);
  transition: background var(--transition-speed) ease;
}

/* ヘッダー */
.app-header {
  text-align: center;
  margin-bottom: 24px;
}

.app-title {
  font-size: 1.85rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #f1f5f9;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.3);
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-top: 6px;
}

/* 時計表示ラッパー */
.clock-display-wrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  max-width: 480px;
  padding: 12px;
}

/* アナログ時計本体コンテナ */
.analog-clock-container {
  --clock-radius: 148px;
  position: relative;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  padding: 12px;
  display: flex;
  justify-content: center;
  align-items: center;
  user-select: none;
  transition: background var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

@media (min-width: 480px) {
  .analog-clock-container {
    --clock-radius: 168px;
    width: 360px;
    height: 360px;
  }
}

/* 文字盤（外枠・ベース） */
.clock-face {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  overflow: hidden;
  transition: background var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

/* 文字盤内部（目盛りや針の配置レイヤー） */
.clock-dial {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 50%;
}

/* 目盛り（時・分）- 文字盤中心軸で正確に回転配置 */
.minute-tick {
  position: absolute;
  top: 0;
  left: 50%;
  width: 2px;
  height: 8px;
  margin-left: -1px;
  transform-origin: 50% var(--clock-radius);
  border-radius: 1px;
  transition: background-color var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

.hour-mark {
  position: absolute;
  top: 0;
  left: 50%;
  width: 4px;
  height: 14px;
  margin-left: -2px;
  transform-origin: 50% var(--clock-radius);
  border-radius: 2px;
  transition: background-color var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

/* 時計の数字 (1〜12) */
.hour-number {
  position: absolute;
  font-weight: 600;
  font-size: 1.15rem;
  line-height: 1;
  text-align: center;
  transform: translate(-50%, -50%);
  transition: color var(--transition-speed) ease, text-shadow var(--transition-speed) ease;
}

/* デジタル情報小窓 (日付・時間) */
.clock-digital-box {
  position: absolute;
  top: 66%;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 4px 10px;
  border-radius: 6px;
  font-family: var(--font-mono);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.4);
  z-index: 5;
  pointer-events: none;
  transition: background-color var(--transition-speed) ease, border-color var(--transition-speed) ease, color var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

.digital-date {
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.digital-time {
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  margin-top: 2px;
}

/* 針の共通スタイル (transformはリアルタイムアニメーションのため除外し、色と影のみtransition適用) */
.hand {
  position: absolute;
  bottom: 50%;
  left: 50%;
  border-radius: 4px 4px 0 0;
  transform-origin: 50% 100%;
  z-index: 10;
  pointer-events: none;
  transition: background-color var(--transition-speed) ease, background var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

/* 時針 */
.hour-hand {
  width: 7px;
  height: 28%;
  margin-left: -3.5px;
  z-index: 10;
}

/* 分針 */
.minute-hand {
  width: 4.5px;
  height: 40%;
  margin-left: -2.25px;
  z-index: 12;
}

/* 秒針 */
.second-hand {
  width: 2px;
  height: 48%;
  margin-left: -1px;
  z-index: 15;
}

/* 秒針の後ろに伸びるカウンターウェイト効果 (針の回転軸 50% 100% から正確に下方向に配置) */
.second-hand::after {
  content: '';
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  width: 4px;
  height: 22px;
  background-color: inherit;
  border-radius: 0 0 2px 2px;
  transition: background-color var(--transition-speed) ease;
}

/* 中央の留め具キャップ */
.center-cap {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 14px;
  height: 14px;
  margin-top: -7px;
  margin-left: -7px;
  border-radius: 50%;
  z-index: 20;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.4);
  transition: background var(--transition-speed) ease, border-color var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

/* ===================================================
   テーマバリエーション定義
   =================================================== */

/* 1. クラシック (Classic: 高級アナログ時計・クリーム文字盤・ローマ/アラビア風) */
.theme-classic.analog-clock-container {
  background: linear-gradient(145deg, #d4af37, #8a7322);
  box-shadow:
    0 15px 35px rgba(0, 0, 0, 0.6),
    inset 0 3px 6px rgba(255, 255, 255, 0.4),
    inset 0 -3px 6px rgba(0, 0, 0, 0.6);
}

.theme-classic .clock-face {
  background: radial-gradient(circle, #fcfbf7 60%, #e9e4d1 100%);
  box-shadow: inset 0 0 16px rgba(0, 0, 0, 0.2);
}

.theme-classic .hour-mark {
  background-color: #2b2b2b;
}

.theme-classic .minute-tick {
  background-color: #78716c;
}

.theme-classic .hour-number {
  color: #1c1917;
  font-family: 'Times New Roman', Times, serif;
  font-weight: 700;
}

.theme-classic .hour-hand {
  background-color: #1c1917;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.35);
}

.theme-classic .minute-hand {
  background-color: #292524;
  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.35);
}

.theme-classic .second-hand {
  background-color: #b91c1c;
}

.theme-classic .center-cap {
  background: radial-gradient(circle, #d4af37 30%, #78350f 100%);
  border: 1px solid #451a03;
}

.theme-classic .clock-digital-box {
  background: #f1ede1;
  border: 1px solid #d6cfbe;
  color: #292524;
}

/* 2. モダン (Modern: クールホワイト＆スカイブルー・ミニマルデザイン) */
.theme-modern.analog-clock-container {
  background: linear-gradient(145deg, #f8fafc, #cbd5e1);
  box-shadow:
    0 16px 36px rgba(0, 0, 0, 0.3),
    inset 0 2px 4px rgba(255, 255, 255, 0.8),
    inset 0 -2px 4px rgba(100, 116, 139, 0.4);
}

.theme-modern .clock-face {
  background: #ffffff;
  box-shadow: inset 0 0 20px rgba(148, 163, 184, 0.15);
}

.theme-modern .hour-mark {
  background-color: #0284c7;
}

.theme-modern .minute-tick {
  background-color: #cbd5e1;
}

.theme-modern .hour-number {
  color: #0f172a;
  font-family: var(--font-main);
  font-weight: 600;
}

.theme-modern .hour-hand {
  background-color: #0f172a;
  box-shadow: 0 3px 6px rgba(15, 23, 42, 0.2);
}

.theme-modern .minute-hand {
  background-color: #334155;
  box-shadow: 0 4px 8px rgba(15, 23, 42, 0.2);
}

.theme-modern .second-hand {
  background-color: #0284c7;
}

.theme-modern .center-cap {
  background: #0284c7;
  border: 2px solid #ffffff;
}

.theme-modern .clock-digital-box {
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  color: #0f172a;
}

/* 3. ダーク (Dark: 深海ネイビー＆サイバー・ネオンルック) */
.theme-dark.analog-clock-container {
  background: linear-gradient(145deg, #334155, #0f172a);
  box-shadow:
    0 20px 40px rgba(0, 0, 0, 0.8),
    inset 0 2px 4px rgba(255, 255, 255, 0.1),
    inset 0 -2px 4px rgba(0, 0, 0, 0.9);
}

.theme-dark .clock-face {
  background: radial-gradient(circle, #1e293b 0%, #090d16 100%);
  box-shadow: inset 0 0 24px rgba(0, 0, 0, 0.9);
}

.theme-dark .hour-mark {
  background-color: #38bdf8;
  box-shadow: 0 0 6px rgba(56, 189, 248, 0.7);
}

.theme-dark .minute-tick {
  background-color: #475569;
}

.theme-dark .hour-number {
  color: #f1f5f9;
  font-family: var(--font-main);
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.3);
}

.theme-dark .hour-hand {
  background-color: #f8fafc;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);
}

.theme-dark .minute-hand {
  background-color: #94a3b8;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);
}

.theme-dark .second-hand {
  background-color: #f43f5e;
  box-shadow: 0 0 8px rgba(244, 63, 94, 0.8);
}

.theme-dark .center-cap {
  background: #38bdf8;
  border: 2px solid #0f172a;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.8);
}

.theme-dark .clock-digital-box {
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid #334155;
  color: #38bdf8;
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.6);
}

/* 4. ゴールド (Gold: ラグジュアリー・シャンパンゴールド＆ブラック) */
.theme-gold.analog-clock-container {
  background: linear-gradient(135deg, #e6c875 0%, #a67c1e 50%, #4a3407 100%);
  box-shadow:
    0 20px 45px rgba(0, 0, 0, 0.7),
    inset 0 3px 6px rgba(255, 255, 255, 0.5),
    inset 0 -3px 6px rgba(0, 0, 0, 0.8);
}

.theme-gold .clock-face {
  background: radial-gradient(circle, #1a1610 20%, #0d0a06 100%);
  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.85);
}

.theme-gold .hour-mark {
  background: linear-gradient(to bottom, #fde047, #ca8a04);
  box-shadow: 0 0 6px rgba(234, 179, 8, 0.5);
}

.theme-gold .minute-tick {
  background-color: #715520;
}

.theme-gold .hour-number {
  color: #facc15;
  font-family: 'Times New Roman', Times, serif;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.8);
}

.theme-gold .hour-hand {
  background: linear-gradient(to right, #facc15, #ca8a04);
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.7);
}

.theme-gold .minute-hand {
  background: linear-gradient(to right, #fde047, #a16207);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.7);
}

.theme-gold .second-hand {
  background-color: #fbbf24;
}

.theme-gold .center-cap {
  background: radial-gradient(circle, #fde047, #854d0e);
  border: 1px solid #fef08a;
  box-shadow: 0 0 8px rgba(250, 204, 21, 0.6);
}

.theme-gold .clock-digital-box {
  background: rgba(26, 22, 16, 0.9);
  border: 1px solid #854d0e;
  color: #facc15;
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.8);
}


/* ===================================================
   時計コントロール パネル
   =================================================== */

.controls-panel {
  width: 100%;
  max-width: 580px;
  background-color: var(--panel-bg);
  backdrop-filter: blur(12px);
  border: 1px solid var(--panel-border);
  box-shadow: var(--panel-shadow);
  border-radius: 16px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 12px;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

@media (min-width: 540px) {
  .control-group {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }
}

.control-label {
  font-size: 0.9rem;
  font-weight: 500;
  color: #cbd5e1;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 110px;
}

/* テーマセレクターボタングループ */
.theme-selector {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  width: 100%;
  max-width: 380px;
}

.theme-btn {
  background-color: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: #cbd5e1;
  font-size: 0.85rem;
  font-weight: 500;
  padding: 8px 10px;
  border-radius: 8px;
  cursor: pointer;
  transition: all var(--transition-speed) ease;
  text-align: center;
}

.theme-btn:hover {
  background-color: rgba(51, 65, 85, 0.8);
  color: #ffffff;
}

.theme-btn-active {
  background-color: #0284c7;
  border-color: #38bdf8;
  color: #ffffff;
  font-weight: 600;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.4);
}

/* 2択トグルボタン群 */
.toggle-btn-group {
  display: flex;
  background-color: rgba(15, 23, 42, 0.7);
  padding: 3px;
  border-radius: 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  width: 100%;
  max-width: 260px;
}

.toggle-btn {
  flex: 1;
  background: transparent;
  border: none;
  color: #94a3b8;
  padding: 6px 12px;
  font-size: 0.82rem;
  font-weight: 500;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
}

.toggle-btn:hover {
  color: #f1f5f9;
}

.toggle-btn-active {
  background-color: #334155;
  color: #38bdf8;
  font-weight: 600;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
}

/* タイムゾーン セレクトボックス */
.timezone-select {
  background-color: rgba(15, 23, 42, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #f8fafc;
  font-size: 0.88rem;
  padding: 8px 14px;
  border-radius: 8px;
  outline: none;
  cursor: pointer;
  width: 100%;
  max-width: 260px;
  transition: border-color var(--transition-speed) ease;
}

.timezone-select:focus {
  border-color: var(--accent-color);
  box-shadow: 0 0 0 1px var(--accent-color);
}

.timezone-select option {
  background-color: #0f172a;
  color: #f8fafc;
}

/* フッター */
.clock-footer {
  margin-top: 24px;
  text-align: center;
  font-size: 0.8rem;
  color: #64748b;
}

export type ClockTheme = 'classic' | 'modern' | 'dark' | 'gold';

export type HandMovement = 'smooth' | 'step';

export type DialStyle = 'numbers' | 'roman' | 'minimal';

export interface ClockSettings {
  theme: ClockTheme;
  movement: HandMovement;
  showDigital: boolean;
  showDate: boolean;
  showSeconds: boolean;
  timeZoneOffset: number; // UTCからの時差（時間単位。例: 日本=9, ロンドン=0, NY=-5）
  iana?: string; // IANAタイムゾーン識別子（例: 'Asia/Tokyo', 'America/New_York'）
  dialStyle?: DialStyle; // 文字盤形式
}

export interface TimeData {
  hours: number;
  minutes: number;
  seconds: number;
  milliseconds: number;
  dateString: string;
  timeString: string;
}

export interface TimeZoneOption {
  label: string;
  city: string;
  offset: number;
  iana?: string; // IANAタイムゾーン識別子
}

import { ClockSettings, TimeData } from '../types';

interface AnalogClockProps {
  settings: ClockSettings;
  timeData: TimeData;
}

// 1〜12の文字盤数字の座標を事前計算（レンダリング毎の再計算を防止）
const CLOCK_NUMBERS = Array.from({ length: 12 }, (_, i) => {
  const num = i + 1;
  const angleRad = (num * 30 - 90) * (Math.PI / 180);
  const radius = 38; // 外周からの相対距離（パーセンテージ）
  const x = 50 + radius * Math.cos(angleRad);
  const y = 50 + radius * Math.sin(angleRad);
  return { num, x, y };
});

// ローマ数字表記
const ROMAN_NUMERALS = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII'];

// 60本の目盛り定義（5分毎は時目盛り、その他は分目盛り）
const CLOCK_TICKS = Array.from({ length: 60 }, (_, i) => ({
  id: i,
  isHour: i % 5 === 0,
  angle: i * 6,
}));

export default function AnalogClock({ settings, timeData }: AnalogClockProps) {
  const { theme, movement, showDigital, showDate, showSeconds, dialStyle } = settings;
  const { hours, minutes, seconds, milliseconds, dateString, timeString } = timeData;

  // 時針・分針・秒針の角度計算
  const secondDeg = movement === 'smooth'
    ? seconds * 6 + milliseconds * 0.006
    : seconds * 6;
  const minuteDeg = minutes * 6 + seconds * 0.1;
  const hourDeg = (hours % 12) * 30 + minutes * 0.5;

  // テーマクラス決定
  const themeClass = `theme-${theme}`;

  return (
    <div
      className={`analog-clock-container ${themeClass}`}
      role="img"
      aria-label={`現在時刻: ${timeString}`}
    >
      <div className="clock-face">
        <div className="clock-dial">
          {/* 目盛り（親コンテナの中央50% 50%を回転中心として正確に円周配置） */}
          {CLOCK_TICKS.map((tick) => (
            <div
              key={tick.id}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                transform: `rotate(${tick.angle}deg)`,
                pointerEvents: 'none',
              }}
            >
              <div className={tick.isHour ? 'hour-mark' : 'minute-tick'} />
            </div>
          ))}

          {/* 文字盤スタイル（数字・ローマ数字・ミニマル）に応じた表示 */}
          {dialStyle !== 'minimal' &&
            CLOCK_NUMBERS.map(({ num, x, y }) => (
              <div
                key={num}
                className="hour-number"
                style={{
                  left: `${x}%`,
                  top: `${y}%`,
                }}
              >
                {dialStyle === 'roman' ? ROMAN_NUMERALS[num - 1] : num}
              </div>
            ))}

          {/* デジタル情報小窓 */}
          {(showDigital || showDate) && (
            <div className="clock-digital-box">
              {showDate && <div className="digital-date">{dateString}</div>}
              {showDigital && <div className="digital-time">{timeString}</div>}
            </div>
          )}

          {/* 時針 */}
          <div
            className="hand hour-hand"
            style={{
              transform: `rotate(${hourDeg}deg)`,
            }}
          />

          {/* 分針 */}
          <div
            className="hand minute-hand"
            style={{
              transform: `rotate(${minuteDeg}deg)`,
            }}
          />

          {/* 秒針 */}
          {showSeconds && (
            <div
              className="hand second-hand"
              style={{
                transform: `rotate(${secondDeg}deg)`,
              }}
            />
          )}

          {/* 中央留め具キャップ */}
          <div className="center-cap" />
        </div>
      </div>
    </div>
  );
}

import { ClockSettings, ClockTheme, HandMovement, TimeZoneOption } from '../types';

interface ClockControlsProps {
  settings: ClockSettings;
  onChangeSettings: (newSettings: Partial<ClockSettings>) => void;
}

const TIMEZONES: TimeZoneOption[] = [
  { label: '東京 (JST)', city: 'Asia/Tokyo', offset: 9 },
  { label: 'シドニー (AEST)', city: 'Australia/Sydney', offset: 10 },
  { label: 'ロンドン (GMT/UTC)', city: 'Europe/London', offset: 0 },
  { label: 'パリ (CET)', city: 'Europe/Paris', offset: 1 },
  { label: 'ニューヨーク (EST)', city: 'America/New_York', offset: -5 },
  { label: 'ロサンゼルス (PST)', city: 'America/Los_Angeles', offset: -8 },
];

const THEMES: { id: ClockTheme; label: string }[] = [
  { id: 'classic', label: 'クラシック' },
  { id: 'modern', label: 'モダン' },
  { id: 'dark', label: 'ダーク' },
