import { useState, useEffect, useCallback } from 'react';
import { ClockSettings, TimeData } from './types';
import AnalogClock from './components/AnalogClock';
import ClockControls from './components/ClockControls';

const STORAGE_KEY = 'precision_clock_settings';

const DEFAULT_SETTINGS: ClockSettings = {
  theme: 'classic',
  movement: 'smooth',
  showDigital: true,
  showDate: true,
  showSeconds: true,
  timeZoneOffset: 9, // 日本標準時 (JST, UTC+9)
  iana: 'Asia/Tokyo',
  dialStyle: 'numbers',
};

// タイムゾーンオフセットからIANAタイムゾーン文字列へのフォールバック辞書
const OFFSET_TO_IANA: Record<number, string> = {
  9: 'Asia/Tokyo',
  10: 'Australia/Sydney',
  0: 'Europe/London',
  1: 'Europe/Paris',
  [-5]: 'America/New_York',
  [-8]: 'America/Los_Angeles',
};

// Intl.DateTimeFormat のインスタンスキャッシュ
const formatterCache = new Map<string, Intl.DateTimeFormat>();

function getFormatter(timeZone: string): Intl.DateTimeFormat {
  let formatter = formatterCache.get(timeZone);
  if (!formatter) {
    formatter = new Intl.DateTimeFormat('ja-JP', {
      timeZone,
      month: 'numeric',
      day: 'numeric',
      weekday: 'short',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric',
      hour12: false,
    });
    formatterCache.set(timeZone, formatter);
  }
  return formatter;
}

function loadSavedSettings(): ClockSettings {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      return { ...DEFAULT_SETTINGS, ...parsed };
    }
  } catch (err) {
    console.error('設定の復元に失敗しました:', err);
  }
  return DEFAULT_SETTINGS;
}

export default function App() {
  const [settings, setSettings] = useState<ClockSettings>(loadSavedSettings);

  // Intl.DateTimeFormat を用いて夏時間を含む正確な地域日時を算出
  const calculateTimeData = useCallback((offsetHours: number, ianaZone?: string): TimeData => {
    const now = new Date();
    const timeZone = ianaZone || OFFSET_TO_IANA[offsetHours] || 'UTC';

    try {
      const formatter = getFormatter(timeZone);
      const parts = formatter.formatToParts(now);
      const partMap: Record<string, string> = {};
      for (const part of parts) {
        partMap[part.type] = part.value;
      }

      const hours = parseInt(partMap.hour || '0', 10) % 24;
      const minutes = parseInt(partMap.minute || '0', 10);
      const seconds = parseInt(partMap.second || '0', 10);
      const milliseconds = now.getMilliseconds();

      const month = partMap.month || '1';
      const day = partMap.day || '1';
      const weekday = partMap.weekday || '';
      const dateString = `${month}/${day} (${weekday})`;

      const pad = (n: number) => String(n).padStart(2, '0');
      const timeString = `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`;

      return {
        hours,
        minutes,
        seconds,
        milliseconds,
        dateString,
        timeString,
      };
    } catch {
      // フォールバック処理
      const hours = (now.getUTCHours() + offsetHours + 24) % 24;
      const minutes = now.getUTCMinutes();
      const seconds = now.getUTCSeconds();
      const milliseconds = now.getMilliseconds();
      const pad = (n: number) => String(n).padStart(2, '0');

      return {
        hours,
        minutes,
        seconds,
        milliseconds,
        dateString: `${now.getMonth() + 1}/${now.getDate()}`,
        timeString: `${pad(hours)}:${pad(minutes)}:${pad(seconds)}`,
      };
    }
  }, []);

  const [timeData, setTimeData] = useState<TimeData>(() =>
    calculateTimeData(settings.timeZoneOffset, settings.iana)
  );

  // 針の動作（smooth / step）に応じたタイマーループの最適化
  useEffect(() => {
    if (settings.movement === 'smooth') {
      let animId: number;
      const tick = () => {
        setTimeData(calculateTimeData(settings.timeZoneOffset, settings.iana));
        animId = requestAnimationFrame(tick);
      };

      animId = requestAnimationFrame(tick);
      return () => cancelAnimationFrame(animId);
    } else {
      // stepモード: 1秒ごとに更新し不要な描画負荷を防止
      setTimeData(calculateTimeData(settings.timeZoneOffset, settings.iana));

      let intervalId: ReturnType<typeof setInterval>;
      const delayToNextSecond = 1000 - (Date.now() % 1000);

      const timeoutId = setTimeout(() => {
        setTimeData(calculateTimeData(settings.timeZoneOffset, settings.iana));
        intervalId = setInterval(() => {
          setTimeData(calculateTimeData(settings.timeZoneOffset, settings.iana));
        }, 1000);
      }, delayToNextSecond);

      return () => {
        clearTimeout(timeoutId);
        if (intervalId) clearInterval(intervalId);
      };
    }
  }, [settings.movement, settings.timeZoneOffset, settings.iana, calculateTimeData]);

  // 設定更新および localStorage への永続化
  const handleUpdateSettings = (partial: Partial<ClockSettings>) => {
    setSettings((prev) => {
      const nextSettings = { ...prev, ...partial };
      // タイムゾーンが変更された場合、対応するIANA識別子も同期
      if (partial.timeZoneOffset !== undefined && !partial.iana) {
        nextSettings.iana = OFFSET_TO_IANA[partial.timeZoneOffset] || prev.iana;
      }
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(nextSettings));
      } catch (err) {
        console.error('設定の保存に失敗しました:', err);
      }
      return nextSettings;
    });
  };

  return (
    <div className="clock-app">
      <header className="app-header">
        <h1 className="app-title">Precision Analog Clock</h1>
        <p className="app-subtitle">高機能リアルタイム アナログ時計</p>
      </header>

      <main className="clock-display-wrapper">
        <AnalogClock settings={settings} timeData={timeData} />
      </main>

      <ClockControls
        settings={settings}
        onChangeSettings={handleUpdateSettings}
      />

      <footer className="clock-footer">
        <p>© 2025 Precision Clock App. Smooth Motion & Multi-Theme Engine.</p>
      </footer>
    </div>
  );
}
